import { DataTable } from "@/components/data-table/data-table";
import { DataTableToolbar } from "@/components/data-table/data-table-toolbar";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { useDataTableRouter } from "@/hooks/use-data-table-router";
import { globalErrorToast, globalSuccessToast } from "@/lib/toast";
import { pageHead } from "@/utils/page-head";
import { requirePermission } from "@/utils/require-permission";
import { queryClient, trpc } from "@/utils/trpc";
import { useMutation, useQuery } from "@tanstack/react-query";
import { createColumnHelper, type ColumnDef } from "@tanstack/react-table";
import { createFileRoute, Link } from "@tanstack/react-router";
import { CheckCircle2, ChevronRight, Clock } from "lucide-react";
import { useMemo } from "react";
import { z } from "zod";

export const Route = createFileRoute("/(core)/back-office/order-pelatihan/")({
  validateSearch: z.object({
    page: z.number().int().positive().default(1),
    perPage: z.number().int().positive().default(20),
    sort: z
      .array(
        z.object({
          id: z.string(),
          desc: z.boolean(),
        }),
      )
      .default([{ id: "createdAt", desc: true }]),
    createdAt: z.array(z.coerce.number()).default([]),
    filters: z.array(z.any()).default([]),
    joinOperator: z.enum(["and", "or"]).default("and"),
    showDeleted: z.boolean().default(false),
    status: z.string().optional(),
  }),
  beforeLoad: async ({ context }) =>
    await requirePermission(context, { permission: "pelatihan.view" }),
  component: RouteComponent,
  head: () => pageHead("Order Pelatihan"),
});

type PelatihanOrder = {
  id: string;
  orderNumber: string;
  status: string;
  paymentStatus: string;
  approvalStatus: string;
  totalAmount: number;
  createdAt: string;
  user: { id: string; name: string; email: string } | null;
  items: { id: string; pelatihan: { id: string; title: string } }[];
  paymentProofUrl: string | null;
  paymentProofUploadedAt: string | null;
  verifiedAt: string | null;
};

const ORDER_STATUS_LABELS: Record<string, string> = {
  pending: "Menunggu Persetujuan",
  waiting_payment: "Menunggu Pembayaran",
  waiting_verification: "Menunggu Verifikasi",
  verified: "Terverifikasi",
  cancelled: "Dibatalkan",
  expired: "Kadaluarsa",
  rejected: "Ditolak",
};

const ORDER_STATUS_VARIANTS: Record<
  string,
  "default" | "secondary" | "destructive" | "outline"
> = {
  pending: "secondary",
  waiting_payment: "secondary",
  waiting_verification: "outline",
  verified: "default",
  cancelled: "destructive",
  expired: "destructive",
  rejected: "destructive",
};

const STATUS_FILTERS = [
  { label: "Semua", value: "all" },
  { label: "Menunggu Persetujuan", value: "pending" },
  { label: "Menunggu Bayar", value: "waiting_payment" },
  { label: "Menunggu Verifikasi", value: "waiting_verification" },
  { label: "Terverifikasi", value: "verified" },
];

const columnHelper = createColumnHelper<PelatihanOrder>();

function useColumns(
  currentPage: number,
  perPage: number,
  onVerify: (orderId: string) => void,
  isVerifying: boolean,
  verifyingId: string | null,
): ColumnDef<PelatihanOrder, any>[] {
  return useMemo(
    () => [
      columnHelper.display({
        id: "no",
        header: "No",
        cell: (info) => (currentPage - 1) * perPage + info.row.index + 1,
      }),
      columnHelper.accessor("orderNumber", {
        header: "No. Order",
        cell: (info) => (
          <span className="font-mono text-sm font-semibold">
            {info.getValue()}
          </span>
        ),
      }),
      columnHelper.accessor("user", {
        header: "Peserta",
        cell: (info) => {
          const user = info.getValue();
          if (!user) return <span className="text-muted-foreground">-</span>;
          return (
            <div>
              <p className="text-sm font-medium">{user.name}</p>
              <p className="text-xs text-muted-foreground">{user.email}</p>
            </div>
          );
        },
      }),
      columnHelper.accessor("items", {
        header: "Pelatihan",
        cell: (info) => {
          const items = info.getValue();
          return (
            <div className="space-y-1">
              {items.slice(0, 2).map((item: any) => (
                <p key={item.id} className="line-clamp-1 text-xs">
                  {item.pelatihan.title}
                </p>
              ))}
              {items.length > 2 && (
                <p className="text-xs text-muted-foreground">
                  +{items.length - 2} lainnya
                </p>
              )}
            </div>
          );
        },
      }),
      columnHelper.accessor("totalAmount", {
        header: "Total",
        cell: (info) => (
          <span className="text-sm font-semibold">
            Rp {info.getValue().toLocaleString("id-ID")}
          </span>
        ),
      }),
      columnHelper.accessor("status", {
        header: "Status",
        cell: (info) => {
          const order = info.row.original;
          let label = ORDER_STATUS_LABELS[order.status] ?? order.status;
          let variant = ORDER_STATUS_VARIANTS[order.status] ?? "secondary";

          if (order.approvalStatus === "pending") {
            label = "Menunggu Persetujuan";
            variant = "secondary";
          } else if (order.approvalStatus === "rejected") {
            label = "Order Ditolak";
            variant = "destructive";
          } else if (order.paymentStatus === "rejected") {
            label = "Pembayaran Ditolak";
            variant = "destructive";
          }

          return (
            <div className="flex flex-col gap-1">
              <Badge variant={variant} className="w-fit text-xs">
                {label}
              </Badge>
              {order.approvalStatus === "approved" &&
                order.paymentStatus === "paid" && (
                  <span className="ml-1 text-[10px] font-semibold text-green-600">
                    Lunas
                  </span>
                )}
            </div>
          );
        },
      }),
      columnHelper.accessor("createdAt", {
        header: "Tanggal",
        cell: (info) =>
          new Date(info.getValue()).toLocaleDateString("id-ID", {
            day: "numeric",
            month: "short",
            year: "numeric",
          }),
      }),
      columnHelper.display({
        id: "actions",
        header: "Aksi",
        cell: (info) => {
          const order = info.row.original;
          const isThisVerifying = isVerifying && verifyingId === order.id;

          return (
            <div className="flex items-center gap-2">
              {order.status === "waiting_verification" && (
                <Button
                  size="sm"
                  variant="default"
                  className="h-7 text-xs"
                  disabled={isThisVerifying}
                  onClick={() => onVerify(order.id)}
                >
                  <CheckCircle2 className="mr-1 h-3 w-3" />
                  {isThisVerifying ? "Verifikasi..." : "Verifikasi"}
                </Button>
              )}
              <Link
                to="/back-office/order-pelatihan/$orderId"
                params={{ orderId: order.id }}
              >
                <Button size="sm" variant="ghost" className="h-7 text-xs">
                  <ChevronRight className="h-3 w-3" />
                </Button>
              </Link>
            </div>
          );
        },
      }),
    ],
    [currentPage, perPage, onVerify, isVerifying, verifyingId],
  );
}

function RouteComponent() {
  const params = Route.useSearch();
  const navigate = Route.useNavigate();

  const {
    data: ordersData,
    isLoading,
    error,
  } = useQuery(
    trpc.pelatihan.order.getAllOrders.queryOptions({
      page: params.page,
      perPage: params.perPage,
      status: params.status,
    }),
  );

  const verifyMutation = useMutation(
    trpc.pelatihan.order.verifyPayment.mutationOptions({
      onSuccess: async () => {
        await queryClient.invalidateQueries(
          trpc.pelatihan.order.getAllOrders.queryOptions({}),
        );
        globalSuccessToast(
          "Pembayaran berhasil diverifikasi. Peserta otomatis ter-enroll.",
        );
      },
      onError: (err) => {
        globalErrorToast(`Gagal memverifikasi: ${err.message}`);
      },
    }),
  );

  const handleVerify = (orderId: string) => {
    if (
      confirm(
        "Verifikasi pembayaran ini? Peserta akan otomatis di-enroll ke pelatihan.",
      )
    ) {
      verifyMutation.mutate({ orderId });
    }
  };

  const columns = useColumns(
    params.page,
    params.perPage,
    handleVerify,
    verifyMutation.isPending,
    verifyMutation.variables?.orderId ?? null,
  );

  const { table } = useDataTableRouter({
    data: (ordersData?.data ?? []) as PelatihanOrder[],
    columns,
    pageCount: ordersData?.pageCount ?? 0,
    search: params,
    navigate: ({ search: updater }) => {
      navigate({ search: updater });
    },
    initialState: {
      sorting: [{ id: "createdAt", desc: true }],
    },
    getRowId: (row) => row.id,
  });

  return (
    <div className="flex flex-col gap-4">
      {/* Header */}
      <div className="flex flex-col gap-2 sm:flex-row sm:items-center sm:justify-between">
        <div>
          <h1 className="text-xl font-bold">Order Pelatihan</h1>
          <p className="text-sm text-muted-foreground">
            Kelola transaksi dan verifikasi pembayaran pelatihan
          </p>
        </div>
        {ordersData && (
          <Badge variant="secondary" className="self-start sm:self-auto">
            {ordersData.total} total order
          </Badge>
        )}
      </div>

      {/* Status filter */}
      <div className="flex flex-wrap gap-2">
        {STATUS_FILTERS.map((f) => (
          <Button
            key={f.value}
            size="sm"
            variant={
              (params.status ?? "all") === f.value ? "default" : "outline"
            }
            onClick={() =>
              navigate({
                to: "/back-office/order-pelatihan",
                search: {
                  ...params,
                  status: f.value === "all" ? undefined : f.value,
                  page: 1,
                },
              })
            }
          >
            {f.value === "waiting_verification" && (
              <Clock className="mr-1 h-3 w-3" />
            )}
            {f.value === "verified" && (
              <CheckCircle2 className="mr-1 h-3 w-3" />
            )}
            {f.label}
          </Button>
        ))}
      </div>

      <DataTable
        table={table}
        isLoading={isLoading}
        error={error}
        emptyMessage="Tidak ada order pelatihan."
        emptyDescription="Belum ada transaksi pembelian kelas pelatihan."
      >
        <DataTableToolbar table={table} />
      </DataTable>
    </div>
  );
}

